-- Zadatak 7, film 11619: Flushed Away. Upiti su nad tablicom movies.
-- Označi jednu naredbu i pritisni F5, jer pgAdmin kod više naredbi prikaže samo zadnji rezultat.

-- Pokreni jednom u ovom Query Toolu, prije vektorskih upita:
SET hnsw.ef_search = 200;

-- ===== SCENARIJ A =====
-- Tekst: A mouse living in a fancy house gets pushed into the toilet by a different mouse that barged into his home. After traveling through London's civilization he finds himself in a rat city where he meets his new companion

-- A: FTS rang
WITH upit AS (
    SELECT to_tsquery('english', 'A | mouse | living | in | a | fancy | house | gets | pushed | into | the | toilet | by | a | different | mouse | that | barged | into | his | home | After | traveling | through | Londons | civilization | he | finds | himself | in | a | rat | city | where | he | meets | his | new | companion') AS q
), rangirano AS (
    SELECT movie_id, title,
           rank() OVER (ORDER BY ts_rank(fts, q) DESC) AS pozicija
    FROM movies, upit
    WHERE fts @@ q
)
SELECT pozicija, title
FROM rangirano
WHERE movie_id = 11619;

